import React, { useState, useEffect } from 'react';
import { createUser, getUsers, deleteUser, updateUser } from '../services/api'; // Add API functions to get, delete, and update users
import { getFranchises } from '../services/api'; // Import API function to get franchises

const UserManagement = () => {
  const [formData, setFormData] = useState({
    username: '',
    password: '',
    name: '',
    role: 'user',
    franchiseId: '',
  });

  const [franchises, setFranchises] = useState([]);
  const [users, setUsers] = useState([]); // State to store the list of users

  // Fetch the list of franchises and users when the component mounts
  useEffect(() => {
    const fetchFranchisesAndUsers = async () => {
      try {
        const franchiseResponse = await getFranchises();
        setFranchises(franchiseResponse.data);

        const userResponse = await getUsers();
        setUsers(userResponse.data);
      } catch (error) {
        alert('Error fetching data: ' + (error.response?.data?.message || error.message));
      }
    };
    fetchFranchisesAndUsers();
  }, []); // Empty dependency array to run only once when the component mounts

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await createUser(formData);
      alert('User created successfully!');
      // Refresh the users list after creating a user
      const userResponse = await getUsers();
      setUsers(userResponse.data);
    } catch (error) {
      alert('Error creating user: ' + (error.response?.data?.message || error.message));
    }
  };

  const handleDelete = async (userId) => {
    try {
      await deleteUser(userId); // Call the API to delete the user
      alert('User deleted successfully!');
      // Refresh the users list after deleting a user
      const userResponse = await getUsers();
      setUsers(userResponse.data);
    } catch (error) {
      alert('Error deleting user: ' + (error.response?.data?.message || error.message));
    }
  };

  const handleEdit = (user) => {
    setFormData({
      username: user.username,
      password: user.password,
      name: user.name,
      role: user.role,
      franchiseId: user.franchise ? user.franchise._id : '',
    });
  };

  const handleUpdate = async (e) => {
    e.preventDefault();
    try {
      await updateUser(formData); // Call the API to update the user
      alert('User updated successfully!');
      // Refresh the users list after updating
      const userResponse = await getUsers();
      setUsers(userResponse.data);
      setFormData({
        username: '',
        password: '',
        name: '',
        role: 'user',
        franchiseId: '',
      }); // Clear the form after updating
    } catch (error) {
      alert('Error updating user: ' + (error.response?.data?.message || error.message));
    }
  };

  return (
    <div>
      <h1>User Management</h1>

      {/* User Creation Form */}
      <form onSubmit={formData.username ? handleUpdate : handleSubmit}>
        <div>
          <label htmlFor="username">Username:</label>
          <input
            id="username"
            name="username"
            placeholder="Username"
            value={formData.username}
            onChange={handleChange}
            required
          />
        </div>
        <div>
          <label htmlFor="password">Password:</label>
          <input
            id="password"
            name="password"
            type="password"
            placeholder="Password"
            value={formData.password}
            onChange={handleChange}
            required
          />
        </div>
        <div>
          <label htmlFor="name">Name:</label>
          <input
            id="name"
            name="name"
            placeholder="Full Name"
            value={formData.name}
            onChange={handleChange}
            required
          />
        </div>
        <div>
          <label htmlFor="role">Role:</label>
          <select id="role" name="role" value={formData.role} onChange={handleChange}>
            <option value="user">User</option>
            <option value="admin">Admin</option>
          </select>
        </div>
        <div>
          <label htmlFor="franchiseId">Franchise:</label>
          <select
            id="franchiseId"
            name="franchiseId"
            value={formData.franchiseId}
            onChange={handleChange}
            required
          >
            <option value="">Select a Franchise</option>
            {franchises.map((franchise) => (
              <option key={franchise._id} value={franchise._id}>
                {franchise.name} - {franchise.location}
              </option>
            ))}
          </select>
        </div>
        <button type="submit">{formData.username ? 'Update User' : 'Create User'}</button>
      </form>

      {/* User List */}
      <h2>User List</h2>
      <table>
        <thead>
          <tr>
            <th>Username</th>
            <th>Name</th>
            <th>Role</th>
            <th>Franchise</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {users.map((user) => (
            <tr key={user._id}>
              <td>{user.username}</td>
              <td>{user.name}</td>
              <td>{user.role}</td>
              <td>
                {user.franchise ? `${user.franchise.name} - ${user.franchise.location}` : 'N/A'}
              </td>
              <td>
                <button onClick={() => handleEdit(user)}>Edit</button>
                <button onClick={() => handleDelete(user._id)}>Delete</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default UserManagement;
